actions.script:
import org.moqui.entity.EntityCondition

def choices = [today:'Today', week:'This week', month:'This month', all:'All time']
period = choices.containsKey(period?.toString()) ? period.toString() : 'today'
periodLabel = choices[period]
def zone = ec.user.timeZone.toZoneId()
def today = ec.user.nowTimestamp.toInstant().atZone(zone).toLocalDate()
def startDay = period == 'today' ? today : (period == 'week' ? today.minusDays(today.dayOfWeek.value - 1) :
        (period == 'month' ? today.withDayOfMonth(1) : null))
def fromTime = startDay ? java.sql.Timestamp.from(startDay.atStartOfDay(zone).toInstant()) : null
def endTime = java.sql.Timestamp.from(today.plusDays(1).atStartOfDay(zone).toInstant())
def fromDate = startDay ? java.sql.Date.valueOf(startDay) : null
def endDate = java.sql.Date.valueOf(today.plusDays(1))
def todayDate = java.sql.Date.valueOf(today)
dateRangeLabel = startDay ? "${ec.l10n.format(fromDate, 'dd MMM yyyy')} – ${ec.l10n.format(todayDate, 'dd MMM yyyy')}" :
        "All dates through ${ec.l10n.format(todayDate, 'dd MMM yyyy')}"
def org = (crmOrganization.activeOrgId ?: '_NA_')
dashboardError = null
leadRows = []; opportunityRows = []; activityRows = []; followupRows = []
stageRows = []; stageSummary = [:]; sourceSummary = [:]
leadStatusNames = [LeadNew:'New', LeadContacted:'Contacted', LeadQualified:'Qualified', LeadConverted:'Converted', LeadLost:'Lost']
leadCount = 0; activeLeadCount = 0; qualifiedRate = 0; openOpportunityCount = 0
pipelineValue = 0G; weightedValue = 0G; wonValue = 0G
activityCount = 0; followupDueCount = 0; unassignedLeads = 0; unattendedLeads = 0
closingSoon = 0; overdueRows = []
if (org && org != '_NA_') {
    try {
        def leadFind = ec.entity.find('zenith.erp.crm.LeadListView').condition('organizationPartyId', org)
        if (fromTime) leadFind.condition('createdDate', EntityCondition.GREATER_THAN_EQUAL_TO, fromTime)
        if (fromTime) leadFind.condition('createdDate', EntityCondition.LESS_THAN, endTime)
        leadRows = leadFind.orderBy('-createdDate').list()
        leadCount = leadRows.size()
        activeLeadCount = leadRows.count { !['LeadConverted','LeadLost'].contains(it.statusId) }
        qualifiedRate = leadCount ? (leadRows.count { it.statusId in ['LeadQualified','LeadConverted'] } * 100 / leadCount).intValue() : 0
        leadRows.each { row ->
            def source = row.sourceName ?: 'Unknown / not set'
            sourceSummary[source] = (sourceSummary[source] ?: 0) + 1
        }

        stageRows = ec.entity.find('mantle.sales.opportunity.SalesOpportunityStage').orderBy('sequenceNum').list()
        stageRows.each { stage -> stageSummary[stage.opportunityStageId] = [name:stage.description, count:0, value:0G] }
        def allOpps = ec.entity.find('zenith.erp.crm.OpportunityListView').condition('organizationPartyId', org).list()
        opportunityRows = allOpps.findAll { row -> !fromDate || (row.estimatedCloseDate && row.estimatedCloseDate >= fromDate && row.estimatedCloseDate < endDate) }
        opportunityRows.each { row ->
            def bucket = stageSummary[row.opportunityStageId]
            if (bucket) { bucket.count++; bucket.value += (row.estimatedAmount ?: 0G) }
            if (!['SoClosedWon','SoClosedLost'].contains(row.opportunityStageId)) {
                openOpportunityCount++
                pipelineValue += (row.estimatedAmount ?: 0G)
                weightedValue += (row.expectedRevenue ?: 0G)
            }
        }
        wonValue = allOpps.findAll { it.opportunityStageId == 'SoClosedWon' && (!fromTime || (it.wonDate && it.wonDate >= fromTime && it.wonDate < endTime)) }
            .sum { it.estimatedAmount ?: 0G } ?: 0G
        closingSoon = allOpps.count { !['SoClosedWon','SoClosedLost'].contains(it.opportunityStageId) &&
            it.estimatedCloseDate && it.estimatedCloseDate >= todayDate && it.estimatedCloseDate <= java.sql.Date.valueOf(today.plusDays(7)) }

        def activityFind = ec.entity.find('zenith.erp.crm.CrmActivity').condition('organizationPartyId', org)
        if (fromTime) activityFind.condition('activityDate', EntityCondition.GREATER_THAN_EQUAL_TO, fromTime)
        if (fromTime) activityFind.condition('activityDate', EntityCondition.LESS_THAN, endTime)
        activityRows = activityFind.orderBy('-activityDate').list()
        activityCount = activityRows.size()
        def allActivityRows = ec.entity.find('zenith.erp.crm.CrmActivity').condition('organizationPartyId', org).list()
        def overdueAll = allActivityRows.findAll { it.statusId == 'Scheduled' && it.dueDate && it.dueDate < ec.user.nowTimestamp }
        followupDueCount = overdueAll.size()
        overdueRows = overdueAll.sort { it.dueDate }.take(6)
        def scheduledLeadIds = allActivityRows.findAll { it.statusId == 'Scheduled' && it.leadId }.collect { it.leadId } as Set
        def allLeadRows = ec.entity.find('zenith.erp.crm.Lead').condition('organizationPartyId', org).list()
        unassignedLeads = allLeadRows.count { !it.assignedToUserId && it.statusId !in ['LeadConverted','LeadLost'] }
        unattendedLeads = allLeadRows.count { it.statusId !in ['LeadConverted','LeadLost'] && !scheduledLeadIds.contains(it.leadId) }
    } catch (Exception e) {
        dashboardError = 'CRM data could not be loaded. Please retry or contact support.'
        leadRows = []; opportunityRows = []; activityRows = []; followupRows = []
        stageSummary = [:]; sourceSummary = [:]
        leadCount = 0; activeLeadCount = 0; qualifiedRate = 0; openOpportunityCount = 0
        pipelineValue = 0G; weightedValue = 0G; wonValue = 0G
        activityCount = 0; followupDueCount = 0; unassignedLeads = 0; unattendedLeads = 0; closingSoon = 0; overdueRows = []
    }
}
hasActiveOrg = org && org != '_NA_'
recentLeads = leadRows.take(6)
recentActivities = activityRows.take(6)
sources = sourceSummary.collect { name, count -> [name:name, count:count] }
        .sort { a, b -> b.count <=> a.count }
def sourceColors = ['#078996', '#4a94f2', '#3ac493', '#ffbd3e', '#ff8656', '#fa6672']
def sourceOffset = 0G
sourceGradient = sources.withIndex().collect { source, index ->
    def start = sourceOffset
    sourceOffset = index == sources.size() - 1 ? 100G : sourceOffset + (source.count * 100G / leadCount)
    "${sourceColors[index % sourceColors.size()]} ${String.format(java.util.Locale.US, '%.2f', start.doubleValue())}% ${String.format(java.util.Locale.US, '%.2f', sourceOffset.doubleValue())}%"
}.join(', ')
maxStageCount = stageSummary.values().collect { it.count }.max() ?: 0
stageRows.each { stage ->
    def bucket = stageSummary[stage.opportunityStageId]
    bucket.barLevel = maxStageCount ? Math.max(1, Math.round(bucket.count * 10.0 / maxStageCount)) : 0
}
